t","alias":"Queue Invest"},{"key":"kiu invast","alias":"Kyoo Invest"},{"key":"k invast lk","alias":"Q Invest LLC"}]},{"id":"5e6b3589-f5ba-55e5-a7af-44187fdcbe59","profileKey":"qa-demo-muhannad-taslaq","entityKind":"PERSON","researchStatus":"PREPARED_PUBLIC_SEED","requiresRefresh":true,"displayName":"Muhannad Taslaq","aliases":["Muhannad Taslaq Alchemist","Muhannad Taslaq Doha","Muhanad Taslaq","Mohannad Taslak","Mohanad Taslak","Muhannad Tasluq","Mohannad Tasluq"],"profileUrl":"https://www.linkedin.com/in/muhannadtaslaq/","role":"Director of Investments","organization":"Alchemist Doha","location":"Doha, Qatar","confidence":"STRONG","facts":[{"claim":"Director of Investments at Alchemist Doha, listed on the Alchemist Doha and team pages.","sourceIds":["S12","S13"],"evidenceClass":"DOCUMENT_SUPPORTED","topic":"ROLE","status":"VERIFIED_AGAINST_SOURCE","asOf":null},{"claim":"Alchemist's team page says he has over 20 years of experience building startups, venture studios and angel networks, and that he leads founder sourcing, supports portfolio companies and connects investors. Alchemist Doha says he manages relationships with regional and global investors and brings founder, CEO, board and exit experience.","sourceIds":["S12","S13"],"evidenceClass":"DOCUMENT_SUPPORTED","topic":"CAREER","status":"VERIFIED_AGAINST_SOURCE","asOf":null},{"claim":"TASMU Accelerator lists him as a serial entrepreneur (Shefa Clinics), an angel investor, a mentor with Alchemist Accelerator in the Bay Area, and a board member of several MENA startups.","sourceIds":["S17"],"evidenceClass":"DOCUMENT_SUPPORTED","topic":"CAREER","status":"VERIFIED_AGAINST_SOURCE","asOf":null},{"claim":"Alchemist Doha is a venture capital and investment platform for tech startups in Qatar and emerging markets, created by Alchemist Accelerator and the QRDI Council (per Gulf Times); it offers founder-friendly investment, structured fundraising support and networking events.","sourceIds":["S12","S16"],"evidenceClass":"MULTI_SOURCE_SUPPORTED","topic":"WHAT_THEY_DO","status":"VERIFIED_AGAINST_SOURCE","asOf":null},{"claim":"At a Startup Grind Doha webinar (reported by Gulf Times, 28 March 2026) he said founders should keep building through a crisis rather than wait and see, outlined six rules (30-day sprints, one metric that matters, knowing the burn rate and \"date of death\"), and warned against raising at distressed valuations unless survival demands it.","sourceIds":["S16"],"evidenceClass":"DOCUMENT_SUPPORTED","topic":"STATEMENT","status":"VERIFIED_AGAINST_SOURCE","asOf":"2026-03-28"},{"claim":"In the same report he told founders to keep investor updates going even when the news is bad, to call their top 10 customers, to use AI to automate repetitive tasks before cutting headcount, and to protect their single most important revenue-generating activity.","sourceIds":["S16"],"evidenceClass":"DOCUMENT_SUPPORTED","topic":"STATEMENT","status":"VERIFIED_AGAINST_SOURCE","asOf":"2026-03-28"},{"claim":"In his LinkedIn post, in a LinkedIn post to founders he argues against pitching multiple startups at once: \"We’re here to back conviction.\" He says Alchemist Doha looks for founders obsessed with a single vision, and asks whether the founder is willing to go all-in on the idea and is the best person to execute it.","sourceIds":["S15"],"evidenceClass":"SELF_REPORTED","topic":"STATEMENT","status":"FACT_EXTRACTED","asOf":null},{"claim":"Priorities visible in his own words: a single committed idea, conviction and clarity, 30-day execution, cash discipline and honest investor communication.","sourceIds":["S15","S16"],"evidenceClass":"SELF_REPORTED","topic":"PRIORITIES","status":"FACT_EXTRACTED","asOf":null},{"claim":"Alchemist Doha, where he is Director of Investments, describes itself as supporting enterprise technology startups across Qatar, the MENA region and emerging markets, integrated with Qatar's ecosystem through the QRDI Council and Innolight.","sourceIds":["S38"],"evidenceClass":"DOCUMENT_SUPPORTED","topic":"ORGANISATION","status":"VERIFIED_AGAINST_SOURCE","asOf":null}],"sources":[{"sourceId":"S12","url":"https://www.alchemistaccelerator.com/doha","description":"Alchemist Doha leadership and investor access","publishedAt":null,"evidenceClass":"read 2026-10-11","status":"VERIFIED_AGAINST_SOURCE","excerpt":"Muhannad builds and manages relationships with regional and global investors and ecosystem partners, and brings founder, CEO, board, and exit experience … Muhannad Taslaq Director of Investments … Alchemist Doha provides structured fundraising support, networking events, and founder-friendly investment.","readAt":"2026-10-11","statusNote":"Official page read 2026-10-11."},{"sourceId":"S13","url":"https://www.alchemistaccelerator.com/team","description":"Alchemist team page listing Muhannad Taslaq as Director of Investments","publishedAt":null,"evidenceClass":"read 2026-10-11","status":"VERIFIED_AGAINST_SOURCE","excerpt":"Muhannad Taslaq has over 20 years of experience building startups, venture studios, and angel networks. He leads founder sourcing, supports portfolio companies, and connects investors … Muhannad Taslaq Director of Investments, Alchemist Doha","readAt":"2026-10-11","statusNote":"Official page read 2026-10-11."},{"sourceId":"S14","url":"https://www.linkedin.com/in/muhannadtaslaq/","description":"Muhannad Taslaq indexed public LinkedIn profile, posts and articles","publishedAt":null,"evidenceClass":"LinkedIn returned HTTP 999 to a plain request on 2026-10-11 (sign-in wall); text not read.","status":"BLOCKED_OR_UNAVAILABLE","excerpt":null,"readAt":null,"statusNote":"LinkedIn returned HTTP 999 to a plain request on 2026-10-11 (sign-in wall); text not read."},{"sourceId":"S15","url":"https://www.linkedin.com/posts/muhannadtaslaq_dear-founders-its-not-a-good-look-to-pitch-activity-7327938415054749696-ndYf","description":"Muhannad Taslaq own words on startup focus and founder conviction","publishedAt":null,"evidenceClass":"read 2026-10-11","status":"FACT_EXTRACTED","excerpt":"It’s not a good look to pitch multiple startups at once … We’re here to back conviction. … We look for founders who are obsessed, those who believe so deeply in a single vision … Is this the idea I’m willing to go all-in on? … We back clarity. We back commitment. We back conviction.","readAt":"2026-10-11","statusNote":"Public LinkedIn post read 2026-10-11."},{"sourceId":"S16","url":"https://www.gulf-times.com/article/722987/business/founders-must-keep-building-through-crisis-says-doha-based-investor","description":"Gulf Times report of Muhannad Taslaq webinar, March 28 2026","publishedAt":null,"evidenceClass":"read 2026-10-11","status":"VERIFIED_AGAINST_SOURCE","excerpt":"Muhannad Taslaq, Director of Investments at Alchemist Doha, drew on lessons he gathered from founders, operators, and investors … “Dilution taken in panic is a cost you would pay for years,” he emphasised … Clarity is a competitive advantage. Smart capital doesn’t disappear in conflicts — it recalibrates. … Taslaq outlined six rules he described as a practical playbook rather than a motivational framework. … shrink the planning horizon to 30-day sprints, identify a single metric that matters and ship continuously … founders must know their exact “burn rate” and calculate what he called their “date of death” … warned against raising at distressed valuations unless survival demands it","readAt":"2026-10-11","statusNote":"News report read 2026-10-11 (Gulf Times, 28 March 2026)."},{"sourceId":"S17","url":"https://accelerator.tasmu.gov.qa/mentors/muhannad-taslaq/","description":"TASMU mentor bio and professional history","publishedAt":null,"evidenceClass":"read 2026-10-11","status":"VERIFIED_AGAINST_SOURCE","excerpt":"Serial Entrepreneur, Shefa Clinics … Muhannad is a mentor with the Alchemist Accelerator in the Bay Area and is serving on the board of several startups in the MENA region","readAt":"2026-10-11","statusNote":"Programme page read 2026-10-11."},{"sourceId":"S38","url":"https://www.alchemistaccelerator.com/doha","description":"Alchemist Doha programme page (re-read 15 Oct 2026)","publishedAt":null,"evidenceClass":"read 2026-10-15","status":"VERIFIED_AGAINST_SOURCE","excerpt":"Alchemist Doha supports enterprise tech startups across Qatar, the MENA region, and emerging markets worldwide. … Deep integration with Qatar's innovation ecosystem through QRDI Council and Innolight.","readAt":"2026-10-15","statusNote":"Read 2026-10-15."}],"quotes":[],"image":{"status":"NOT_ATTACHED","assetUrl":null,"attribution":null,"licenseNote":null},"profile":{"seedVersion":"1.2","verifiedAt":"2026-10-15","oneLine":"Alchemist Doha's Director of Investments; publicly stresses founder conviction and cash discipline.","summary":"Muhannad Taslaq is Director of Investments at Alchemist Doha. Alchemist's team page credits him with over 20 years building startups, venture studios and angel networks, and TASMU lists him as a serial entrepreneur and angel investor. In public he talks about founder conviction, one committed idea, 30-day execution, cash discipline and keeping investors informed, in a LinkedIn post and a March 2026 Gulf Times webinar report.","rehearsal":[{"topic":"founder conviction","question":"Are you fully committed to this one business, or exploring several ventures?","basisSourceIds":["S15"]},{"topic":"early traction and customer evidence","question":"Tell me the strongest signal from a paying customer.","basisSourceIds":["S16"]},{"topic":"cash burn and runway","question":"What is your burn rate and exact runway, and what is your date of death?","basisSourceIds":["S16"]},{"topic":"30-day execution plans","question":"What will you ship in the next 30 days to validate demand?","basisSourceIds":["S16"]},{"topic":"resilience under stress","question":"What is your plan if fundraising takes twice as long?","basisSourceIds":["S16"]}],"rehearsalTopics":["founder conviction","early traction and customer evidence","cash burn and runway","30-day execution plans","resilience under stress"],"rehearsalQuestions":["Are you fully committed to this one business, or exploring several ventures?","Tell me the strongest signal from a paying customer.","What is your burn rate and exact runway, and what is your date of death?","What will you ship in the next 30 days to validate demand?","What is your plan if fundraising takes twice as long?"],"verification":[{"ordinal":0,"status":"VERIFIED","checkedAt":"2026-10-11","basis":"Stated on the official Alchemist Doha team page read 2026-10-11.","note":null},{"ordinal":1,"status":"VERIFIED","checkedAt":"2026-10-11","basis":"Stated on a page read on 2026-10-11; the excerpt is stored with the source.","note":null},{"ordinal":2,"status":"VERIFIED","checkedAt":"2026-10-11","basis":"Stated on a page read on 2026-10-11; the excerpt is stored with the source.","note":null},{"ordinal":3,"status":"VERIFIED","checkedAt":"2026-10-11","basis":"Stated on a page read on 2026-10-11; the excerpt is stored with the source.","note":null},{"ordinal":4,"status":"VERIFIED","checkedAt":"2026-10-11","basis":"Stated on a page read on 2026-10-11; the excerpt is stored with the source.","note":null},{"ordinal":5,"status":"VERIFIED","checkedAt":"2026-10-11","basis":"Stated on a page read on 2026-10-11; the excerpt is stored with the source.","note":null},{"ordinal":6,"status":"PUBLICLY_REPORTED_UNCONFIRMED","checkedAt":"2026-10-11","basis":"Reported by a page read on 2026-10-11 but not independently confirmed.","note":null},{"ordinal":7,"status":"PUBLICLY_REPORTED_UNCONFIRMED","checkedAt":"2026-10-11","basis":"Reported by a page read on 2026-10-11 but not independently confirmed.","note":null},{"ordinal":8,"status":"VERIFIED","checkedAt":"2026-10-15","basis":"Stated on a page read on 2026-10-15; the excerpt is stored with the source.","note":null}],"evidenceAxes":[{"ordinal":0,"truthClass":"USER_CLAIM","evidenceStatus":"DOCUMENT_SUPPORTED","lifecycleStatus":"CURRENT","retrievedAt":"2026-1