n":"1.0","verifiedAt":"2026-10-15","oneLine":"A Qatar Financial Centre-registered angel fund launched in 2018 that provides seed funding to early-stage technology startups.","summary":"A Qatar Financial Centre-registered angel fund launched in 2018 that provides seed funding to early-stage technology startups.","rehearsal":[],"rehearsalTopics":["seed-stage technology","angel syndicate fit"],"rehearsalQuestions":["What milestone does this seed round fund?"],"verification":[{"ordinal":0,"status":"VERIFIED","checkedAt":"2026-10-15","basis":"Stated on a page read on 2026-10-15; the excerpt is stored with the source.","note":null},{"ordinal":1,"status":"VERIFIED","checkedAt":"2026-10-15","basis":"Stated on a page read on 2026-10-15; the excerpt is stored with the source.","note":null}],"evidenceAxes":[{"ordinal":0,"truthClass":"USER_CLAIM","evidenceStatus":"DOCUMENT_SUPPORTED","lifecycleStatus":"HISTORICAL","retrievedAt":"2026-10-15","uncertainty":"Read on the cited page; not independently verified by Capital Q."},{"ordinal":1,"truthClass":"USER_CLAIM","evidenceStatus":"DOCUMENT_SUPPORTED","lifecycleStatus":"HISTORICAL","retrievedAt":"2026-10-15","uncertainty":"Read on the cited page; not independently verified by Capital Q."}],"contradicted":[],"quoteLabels":[],"arabicNames":[]},"lastResearchedAt":"2026-10-15T00:00:00.000Z","aliasRows":[{"key":"duha taC angals","alias":"Doha Tech Angels"},{"key":"dta","alias":"DTA"}]}]$j$::jsonb;
  e jsonb; s jsonb; f jsonb; a jsonb; ord integer;
  links constant jsonb := '{"qa-demo-qdb":"b0075742-0000-4000-8000-0000000000c4","qa-demo-rasmal":"b0075742-0000-4000-8000-0000000000c5","qa-demo-doha-tech-angels":"b0075742-0000-4000-8000-0000000000c6"}'::jsonb;
begin
  for e in select * from jsonb_array_elements(doc) loop
    insert into q_runtime.external_persons
      (id, tenant_id, user_id, entity_kind, research_status, requires_refresh,
       profile_key, display_name, name_variants, profile_url, role,
       organization, location, confidence, image, quotes, profile,
       last_researched_at)
    values ((e->>'id')::uuid, null, null, e->>'entityKind', 'PREPARED_PUBLIC_SEED',
            (e->>'requiresRefresh')::boolean, e->>'profileKey', e->>'displayName',
            e->'aliases', e->>'profileUrl', e->>'role', e->>'organization',
            e->>'location', e->>'confidence', e->'image', e->'quotes', e->'profile',
            (e->>'lastResearchedAt')::timestamptz)
    on conflict (profile_key) where tenant_id is null do update set
      requires_refresh = excluded.requires_refresh,
      display_name = excluded.display_name,
      name_variants = excluded.name_variants,
      quotes = excluded.quotes,
      profile = excluded.profile,
      last_researched_at = excluded.last_researched_at,
      updated_at = clock_timestamp();
    if links ? (e->>'profileKey') then
      update q_runtime.external_persons
         set investor_organisation_id = (links->>(e->>'profileKey'))::uuid
       where id = (e->>'id')::uuid and investor_organisation_id is null;
    end if;
    for a in select * from jsonb_array_elements(e->'aliasRows') loop
      insert into q_runtime.external_entity_aliases (external_person_id, alias_key, alias)
      values ((e->>'id')::uuid, a->>'key', a->>'alias')
      on conflict do nothing;
    end loop;
    for s in select * from jsonb_array_elements(e->'sources') loop
      insert into q_runtime.external_entity_sources
        (external_person_id, source_id, url, description, published_at,
         evidence_class, status, excerpt, read_at, status_note)
      values ((e->>'id')::uuid, s->>'sourceId', s->>'url', s->>'description', null,
              s->>'evidenceClass', s->>'status', s->>'excerpt',
              (s->>'readAt')::timestamptz, s->>'statusNote')
      on conflict (external_person_id, source_id) do update set
        url = excluded.url, description = excluded.description,
        evidence_class = excluded.evidence_class, status = excluded.status,
        excerpt = excluded.excerpt, read_at = excluded.read_at,
        status_note = excluded.status_note;
    end loop;
    ord := 0;
    for f in select * from jsonb_array_elements(e->'facts') loop
      insert into q_runtime.external_entity_facts
        (external_person_id, ordinal, claim, source_ids, evidence_class, topic, status, as_of)
      values ((e->>'id')::uuid, ord, f->>'claim',
              array(select jsonb_array_elements_text(f->'sourceIds')),
              f->>'evidenceClass', f->>'topic', f->>'status', f->>'asOf')
      on conflict (external_person_id, ordinal) do update set
        claim = excluded.claim, source_ids = excluded.source_ids,
        evidence_class = excluded.evidence_class, topic = excluded.topic,
        status = excluded.status, as_of = excluded.as_of;
      ord := ord + 1;
    end loop;
  end loop;
end
$m$;
